pub enum Msg {
    Ping,
    Hello(String),
}

pub fn decode(bytes: &str) -> Result<Msg, String> {
    let payload = bytes.trim();

    match payload {
        "ping" | "v1:ping" => Ok(Msg::Ping),
        payload if payload.starts_with("v:2:hello:") => {
            Ok(Msg::Hello(payload[10..].to_owned()))
        }
        _ => Err("unknown".into()),
    }
}

pub fn encode(msg: &Msg) -> String {
    match msg {
        Msg::Ping => "v1:ping".into(),
        Msg::Hello(value) => format!("v:2:hello:{}", value),
    }
}

#[cfg(test)]
mod tests {
    use super::{decode, encode, Msg};

    #[test]
    fn decodes_current_ping() {
        assert!(matches!(decode("v1:ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn decodes_legacy_ping() {
        assert!(matches!(decode("ping"), Ok(Msg::Ping)));
    }

    #[test]
    fn rejects_payloads_that_only_contain_ping() {
        assert!(decode("not-a-ping").is_err());
    }

    #[test]
    fn encodes_current_ping() {
        assert_eq!(encode(&Msg::Ping), "v1:ping");
    }

    #[test]
    fn encode_roundtrip_ping() {
        let encoded = encode(&Msg::Ping);
        assert!(matches!(decode(&encoded), Ok(Msg::Ping)));
    }

    #[test]
    fn decodes_v2_hello() {
        assert!(matches!(
            decode("v:2:hello:client"),
            Ok(Msg::Hello(name)) if name == "client"
        ));
    }

    #[test]
    fn encodes_v2_hello() {
        assert_eq!(encode(&Msg::Hello("client".into())), "v:2:hello:client");
    }

    #[test]
    fn encode_roundtrip_hello() {
        let encoded = encode(&Msg::Hello("client".into()));
        assert!(matches!(
            decode(&encoded),
            Ok(Msg::Hello(name)) if name == "client"
        ));
    }

    #[test]
    fn rejects_hello_without_v2_envelope() {
        assert!(decode("hello:client").is_err());
        assert!(decode("v2:hello:client").is_err());
    }
}
